CREATE OR REPLACE FORCE EDITIONABLE VIEW "PPPT"."PERSONAHERMAN" ("IDPERSONAL", "INTERPRETACION", "INTERPRETACION1", "INTERPRETACION2", "INTERPRETACION3", "INTERPRETACION4", "INTERPRETACION5", "NOMBRE", "NOMBRE1", "NOMBRE2", "NOMBRE3", "NOMBRE4", "NOMBRE5") AS 
  SELECT PersonalInterpretacion.IdPersonal, Interpretacion.Interpretacion, Interpretacion_1.Interpretacion as Interpretacion1, Interpretacion_2.Interpretacion as Interpretacion2, Interpretacion_3.Interpretacion as Interpretacion3, Interpretacion_4.Interpretacion as Interpretacion4, Interpretacion_5.Interpretacion as Interpretacion5, Interpretacion.Nombre, Interpretacion_1.Nombre as Nombre1, Interpretacion_2.Nombre as Nombre2, Interpretacion_3.Nombre as Nombre3, Interpretacion_4.Nombre as Nombre4, Interpretacion_5.Nombre as Nombre5
   FROM (((((PersonalInterpretacion LEFT JOIN Interpretacion ON PersonalInterpretacion.IdInterpretacion1 = Interpretacion.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_1 ON PersonalInterpretacion.IdInterpretacion2 = Interpretacion_1.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_2 ON PersonalInterpretacion.IdInterpretacion3 = Interpretacion_2.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_3 ON PersonalInterpretacion.IdInterpretacion4 = Interpretacion_3.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_4 ON PersonalInterpretacion.IdInterpretacion5 = Interpretacion_4.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_5 ON PersonalInterpretacion.IdInterpretacion6 = Interpretacion_5.IdInterpretacion
   WHERE (((PersonalInterpretacion.IdPrueba)=5));
